pair Y=dir(120)*(1,0);
pair Z=dir(-100)*(1,0);

real t =60;
pair B=dir(t)*(2.0,0);
pair A=dir(t+130)*(2.86,0);
pair C=dir(t+250)*(1.6,0);

draw(A--B--C--A);
draw(X--Y--Z--X);

label("$A$",A,W);
label("$B$",B,NE);
label("$C$",C,SE);
label("$X$",X,E);
label("$Y$",Y,NW);
label("$Z$",Z,SW);

label("$40^\circ$",A+(.2,.06),E);
label("$80^\circ$",C+(0,.15),NW);

label("$50^\circ$",Z+(.2,0),NE);
